            return default
        for n in names:
            try:
                return obj[n]
            except Exception:
                pass
            try:
                return obj.__dict__[n]
            except Exception:
                pass
        return default

    depot = pick(instance, ("depot",), 0)
    capacity = pick(instance, ("capacity", "vehicle_capacity"), None)
    demand = pick(instance, ("demand", "demands"), None)
    coords = pick(instance, ("coords", "coordinates"), None)
    dist = pick(instance, ("distance_matrix", "distances", "matrix"), None)
    customers = pick(instance, ("customers", "nodes"), None)

    if customers is None:
        if demand is not None:
            customers = list(demand.keys()) if isinstance(demand, dict) else list(range(len(demand)))
        elif coords is not None:
            customers = list(coords.keys()) if isinstance(coords, dict) else list(range(len(coords)))
        elif dist is not None:
            customers = list(range(len(dist)))
        else:
            return []

    customers = [c for c in customers if c != depot]

    def dem(i):
        if demand is None:
            return 1
        if isinstance(demand, dict):
            return demand.get(i, 0)
        return demand[i] if 0 <= i < len(demand) else 0

    def coord(i):
        if coords is None:
            return None
        if isinstance(coords, dict):
            return coords.get(i)
        return coords[i] if 0 <= i < len(coords) else None

    def d(i, j):
        if dist is not None:
            try:
                return dist[i][j]
            except Exception:
                pass
        ci, cj = coord(i), coord(j)
        if ci is None or cj is None:
            return abs(i - j)
        dx = ci[0] - cj[0]
        dy = ci[1] - cj[1]
        return (dx * dx + dy * dy) ** 0.5

    if capacity is None:
        s = 0
        for c in customers:
            s += dem(c)
        capacity = s if s > 0 else 1

    dc = coord(depot)
    if dc is not None:
        def key(c):
            x, y = coord(c)
            dx = x - dc[0]
            dy = y - dc[1]
            return (0 if dy >= 0 else 1, 0 if dx >= 0 else 1, abs(dy) / (abs(dx) + 1e-12), dx * dx + dy * dy, c)
        order = sorted(customers, key=key)
    else:
        order = sorted(customers, key=lambda c: (d(depot, c), -dem(c), c))

    routes, cur, load = [], [], 0
    for c in order:
        x = dem(c)
        if x > capacity:
            if cur:
                routes.append(cur)
                cur, load = [], 0
            routes.append([c])
            continue
        if load + x <= capacity:
            cur.append(c)
            load += x
        else:
            if cur:
                routes.append(cur)
            cur, load = [c], x
    if cur:
        routes.append(cur)

    def rload(r):
        s = 0
        for c in r:
            s += dem(c)
        return s

    def ins_delta(r, pos, c):
        a = depot if pos == 0 else r[pos - 1]
        b = depot if pos == len(r) else r[pos]
        return d(a, c) + d(c, b) - d(a, b)

    seen = set()
    for r in routes:
        for c in r:
            seen.add(c)

    for c in customers:
        if c in seen:
            continue
        best = None
        best_pos = None
        for ri, r in enumerate(routes):
            if rload(r) + dem(c) > capacity:
                continue
            for pos in range(len(r) + 1):
                cand = (ins_delta(r, pos, c), ri, pos)
                if best is None or cand < best:
                    best = cand
                    best_pos = (ri, pos)
        if best_pos is None:
            routes.append([c])
        else:
            ri, pos = best_pos
            routes[ri] = routes[ri][:pos] + [c] + routes[ri][pos:]

    for _ in range(3):
        improved = False
        loads = [rload(r) for r in routes]
        for i in range(len(routes)):
            r1 = routes[i]
            if not r1:
                continue
            for p, c in enumerate(list(r1)):
                dc = dem(c)
                rem = (d(depot, c) + d(c, depot)) if len(r1) == 1 else (d(r1[p - 1] if p > 0 else depot, c) + d(c, r1[p + 1] if p + 1 < len(r1) else depot) - d(r1[p - 1] if p > 0 else depot, r1[p + 1] if p + 1 < len(r1) else depot))
                for j in range(len(routes)):
                    if i == j:
                        continue
                    r2 = routes[j]
                    if loads[j] + dc > capacity:
                        continue
                    best_q, best_gain = None, 0
                    for q in range(len(r2) + 1):
                        gain = rem - ins_delta(r2, q, c)
                        if gain > best_gain + 1e-12 or (abs(gain - best_gain) <= 1e-12 and (best_q is None or q < best_q)):
                            best_gain, best_q = gain, q
                    if best_q is not None and best_gain > 1e-12:
                        r1.pop(p)
                        r2[best_q:best_q] = [c]
                        if not r1:
                            routes[i] = []
                        improved = True
                        break
                if improved:
                    break
            if improved:
                break
        routes = [r for r in routes if r]

    for idx, r in enumerate(routes):
        n = len(r)
        if n < 4:
            continue
        changed = True
        for _ in range(30):
            if not changed:
                break
            changed = False
            best = None
            for i in range(n - 2):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for k in range(i + 1, n - 1):
                    c = r[k]
                    e = depot if k == n - 1 else r[k + 1]
                    gain = (d(a, b) + d(c, e)) - (d(a, c) + d(b, e))
                    if gain > 1e-12 and (best is None or gain > best[0] + 1e-12 or (abs(gain - best[0]) <= 1e-12 and (i, k) < (best[1], best[2]))):
                        best = (gain, i, k)
            if best is not None:
                _, i, k = best
                r[i:k + 1] = reversed(r[i:k + 1])
                changed = True
        routes[idx] = r

    assigned = {}
    for c in customers:
        assigned[c] = 0
    for r in routes:
        for c in r:
            assigned[c] = assigned.get(c, 0) + 1

    for c in customers:
        if assigned.get(c, 0) == 0:
            best = None
            best_pos = None
            for ri, r in enumerate(routes):
                if rload(r) + dem(c) > capacity:
                    continue
                for pos in range(len(r) + 1):
                    cand = (ins_delta(r, pos, c), ri, pos)
                    if best is None or cand < best:
                        best = cand
                        best_pos = (ri, pos)
            if best_pos is None:
                routes.append([c])
            else:
                ri, pos = best_pos
                routes[ri] = routes[ri][:pos] + [c] + routes[ri][pos:]

    return [r for r in routes if r]
